import functools, itertools
def dice(n, faces=6):
    w = [1] + [0] * n
    for s in range(1, n + 1): w[s] = sum(w[s - k] for k in range(1, faces + 1) if k <= s)
    return w[n]
def slow(n): return sum(1 for L in range(1, n + 1) for t in itertools.product(range(1, 7), repeat=L) if sum(t) == n)
result = slow(4)

